{"content":"import unittest

from two_bucket import measure


class MeasureTests(unittest.TestCase):
    def test_pouring_from_bucket_one(self):
        self.assertEqual(measure(3, 5, 1, "one"), (4, "one", 5))

    def test_pouring_from_bucket_two(self):
        self.assertEqual(measure(3, 5, 1, "two"), (8, "two", 3))

    def test_swapped_bucket_sizes(self):
        self.assertEqual(measure(5, 3, 1, "two"), (4, "two", 5))

    def test_first_fill_counts(self):
        self.assertEqual(measure(7, 11, 7, "one"), (1, "one", 0))
        self.assertEqual(measure(7, 11, 11, "two"), (1, "two", 0))

    def test_other_bucket_can_be_filled_directly(self):
        self.assertEqual(measure(3, 5, 5, "one"), (2, "two", 3))
        self.assertEqual(measure(3, 5, 3, "two"), (2, "one", 5))

    def test_forbidden_state_is_not_a_shortcut(self):
        self.assertEqual(measure(2, 3, 1, "one"), (4, "one", 3))
        self.assertEqual(measure(3, 2, 1, "two"), (4, "two", 3))

    def test_common_factor_can_still_allow_goal(self):
        self.assertEqual(measure(6, 10, 2, "one"), (4, "one", 10))

    def test_zero_goal_still_requires_first_fill(self):
        self.assertEqual(measure(3, 5, 0, "one"), (1, "two", 3))

    def test_impossible_goals_raise_with_message(self):
        for args in ((6, 10, 5, "one"), (3, 5, 6, "two")):
            with self.subTest(args=args):
                with self.assertRaisesRegex(ValueError, ".+"):
                    measure(*args)

    def test_invalid_inputs_raise_with_message(self):
        for args in (
            (0, 5, 1, "one"),
            (3, -5, 1, "two"),
            (3, 5, -1, "one"),
            (3, 5, 1, "three"),
            (3.5, 5, 1, "one"),
        ):
            with self.subTest(args=args):
                with self.assertRaisesRegex(ValueError, ".+"):
                    measure(*args)


if __name__ == "__main__":
    unittest.main()
